{
  "summary": "MA1 and RQ with quadratic means are nearly tied and outperform MA3. Quadratic beats constant for MA3, but its benefit for MA1 remains untested. MA3 amplitude modulation offered no improvement; this does not settle modulation for rougher kernels. Next test MA1's mean, multiscale addition, and amplitude modulation, while exploring periodic and smooth-plus-multiscale alternatives.",
  "proposals": [
    {"kernel_id": 2, "mean_id": 2, "reason": "Isolate quadratic mean benefit for the current best covariance."},
    {"kernel_id": 18, "mean_id": 4, "reason": "Test whether rough and multiscale components improve either leading primitive alone."},
    {"kernel_id": 20, "mean_id": 4, "reason": "Test amplitude modulation while holding MA1 roughness and quadratic mean fixed."},
    {"kernel_id": 36, "mean_id": 4, "reason": "Explore a periodic component added to the competitive RQ baseline."},
    {"kernel_id": 11, "mean_id": 4, "reason": "Explore smooth-plus-multiscale covariance, contrasting SE and MA1 additions to RQ."},
    {"kernel_id": 5, "mean_id": 2, "reason": "Reserve: isolate quadratic mean benefit for the other leading covariance."},
    {"kernel_id": 22, "mean_id": 4, "reason": "Reserve: explore periodic modulation of rough covariance rather than an additive periodic component."}
  ]
}
